-- 已有数据库升级用：英文版。推荐活动的“为什么值得去”多一份英文，网页切到英文时显示；没有英文的显示原文。
alter table public.techweek_events add column why_en text check (why_en is null or char_length(why_en) between 1 and 900);
grant select (why_en) on public.techweek_events to anon;

drop policy "anyone adds events" on public.techweek_events;
create policy "anyone adds events" on public.techweek_events for insert to anon
  with check (curated = false and source = 'community' and tw_id is null and featured = false and intro is null and topics is null and why_en is null and why is not null);

update public.techweek_events e set why_en = x.why_en
from jsonb_to_recordset($tw$[{"link": "https://www.tech-week.com/calendar/sf/events/the-future-of-video-intelligence-8d663af9-3ba9-40dd-98a1-485c396a3e55", "why_en": "A fireside chat hosted by Naver Ventures on video-understanding AI. Speakers: Tiffany Luck (Partner, NEA), Jae Lee (Co-founder & CEO, Twelve Labs) and Namsun Kim (CEO of Poshmark and Managing Partner at Naver Ventures), moderated by a Cooley partner. 30 minutes of conversation, 15 minutes of Q&A, then open networking. Good for founders in multimodal and video, with investors in the same room."}, {"link": "https://www.tech-week.com/calendar/sf/events/eon-x-shaun-maguire-fireside-a58c487e-53dc-43d8-94cf-737b913a5e28", "why_en": "Sequoia partner Shaun Maguire in conversation with Eon's CTO Ron Kimchi on building infrastructure for AI agents. Hosted by Eon, in a small room. Good for founders and engineers who want to hear up close how an investor thinks about agent infrastructure."}, {"link": "https://luma.com/szg4hzay", "why_en": "A relaxed get-together for YC founders across batches: no panels, no pitches, just drinks, light bites and founder-to-founder conversation. Approval required; mainly for current batches, alumni and YC-backed companies. You'll be asked for your company and YC batch when you register."}, {"link": "https://partiful.com/e/Fp4oMyFGQC6HzotKXc8T", "why_en": "The official Tech Week opening party, hosted by Fireworks and a16z with support from Vercel, ElevenLabs and Stripe. Rooftop, skyline and live music, with founders, engineers, investors and operators. The best place to meet people on the first night."}, {"link": "https://www.tech-week.com/calendar/sf/events/google-for-startups-engineering-10x-with-dr-astro-teller-and-google-deepmind-b8ad61d1-0cb8-4d07-bf6b-8aacafcb8c60", "why_en": "Astro Teller (Captain of Moonshots at Google X) and Derek Andersen (Bevy / Startup Grind) on balancing moonshot thinking with the reality of building. Then Paige Bailey of Google DeepMind leads a conversation with the founders of Pupper and Surge AI on using Google's frontier models to bring AI into the physical world. There is an expert lounge and live demos off stage. Official Tech Week pick; a Google referral code makes approval easier."}, {"link": "https://partiful.com/e/XaBTYkfWChPrquuI6uPH", "why_en": "Anthropic's home base for Tech Week, open every day from Tuesday to Thursday. By day it is the Claude Cafe: work alongside the Anthropic team, book office hours and meet investors. Panels and workshops run 11:30–16:00 each day, covering AI agents, robotics, fundraising, medical AI and consumer products."}, {"link": "https://www.tech-week.com/calendar/sf/events/capturing-the-value-of-intelligence-sftech-week-a73bb032-f79e-45aa-9340-dc6d6a8c30b6", "why_en": "A panel by HSBC Innovation Banking and a16z on the infrastructure behind the next wave of AI and how to turn it into a business at scale. Speakers: Matt Bornstein (GP, a16z), Anastasios Angelopoulos (CEO, Arena), Anirudh Sriram (CTO, Tessera Labs) and Alex Choy (Managing Director, HSBC). Investors and operators on one stage; good for people building AI infrastructure or wanting to see where the money is going. Official Tech Week pick."}, {"link": "https://www.tech-week.com/calendar/sf/events/the-investment-game-in-pursuit-of-series-a-live-with-a16z-8859ff09-b6a2-4065-85ee-8f55e965ee73", "why_en": "A live, dating-show-style session hosted by HubSpot: three seed-stage founders take turns answering pointed investment questions to win the (hypothetical) Series A backing of a16z partner Emily Bennett. After each round she explains what sparked her interest and what raised red flags, then picks one. A direct look at how a top investor decides; good for founders preparing a Series A. Official Tech Week pick."}, {"link": "https://www.tech-week.com/calendar/sf/events/camp-ai-production-ready-agents-fa378e29-57e0-4583-aa85-56f4e4015894", "why_en": "Hosted by Auth0, on what it takes to move agents from demo to production: security, automation and scale. Speakers: Gareth Davies (CPO, Auth0), Den Delimarsky (core maintainer of MCP and Member of Technical Staff at Anthropic), Rita Kozlov (VP Product, Cloudflare) and Paul Klein IV (Founder & CEO, Browserbase), plus live demos including CircleCI's CTO. The most hands-on agent lineup of the week; good for engineers and founders building agents. Official Tech Week pick."}, {"link": "https://www.tech-week.com/calendar/sf/events/state-of-models-by-openrouter-fcb5966d-45b9-47c3-96a2-f8129a4ae84c", "why_en": "The first edition of OpenRouter's new flagship series: real usage data from the platform on which models are gaining, how developers trade off cost and quality, and where open and closed models each win. Peter Walker of OpenRouter presents the data, then talks with George Cameron (Co-founder, Artificial Analysis), moderated by Jane Alexander (Partner, CapitalG). Talks start at 18:15; networking from 19:25. Good for product and engineering teams choosing models. Official Tech Week pick."}, {"link": "https://www.tech-week.com/calendar/sf/events/pioneer-a-summit-for-cx-leaders-9d5e892d-ff22-410f-98fc-979bee3c1de5", "why_en": "A full-day summit hosted by Fin on customer experience in the age of AI. The highlight is a fireside between Eoghan McCabe (Founder & CEO, Fin) and Aaron Levie (Founder & CEO, Box) on leading a company through the AI transformation; CX leaders from Anthropic, Clay, Kalshi, Gamma and others also speak. Good for people building AI for support and service, or running customer experience. Official Tech Week pick."}, {"link": "https://partiful.com/e/MXd2fC8umpyvOwQ3KP3S", "why_en": "Co-hosted by Google for Startups and NVIDIA. Jen Hoskins (NVIDIA) and Dr. Arman Zaribafiyan (SandboxAQ) cover Quantum-AI and high-velocity inference, with further sessions on securing agentic AI and building a moat. Expert lounge and live demos on site."}, {"link": "https://luma.com/vmjvw2ox", "why_en": "A picnic in Alamo Square Park, a breather between Tech Week panels. International founders and people with international backgrounds are welcome, with priority for YC and international founders. Hosted by Shor (YC S25, international payroll) and LegalOS (YC W26, an AI-native immigration law firm); good for anyone with questions about visas or overseas teams."}, {"link": "https://www.tech-week.com/calendar/sf/events/fireside-chat-with-henry-ward-ceo-of-carta-2af5b5d3-33b9-4568-be3c-14ea942961fe", "why_en": "A fireside chat with Henry Ward, Co-founder & CEO of Carta, on building and scaling a company today: how the founder journey is changing, lessons from Carta, how AI is reshaping company-building, and where the startup ecosystem is heading. Hosted by Georgian Innovation Hub, moderated by Benjamin Brand of Silicon Foundry. Good for early-stage founders. End time not announced."}, {"link": "https://www.tech-week.com/calendar/sf/events/ai-supper-club-4e35408a-b9a6-481e-ac08-b437bb1e0fb9", "why_en": "A small dinner co-hosted by Collaborative Fund, Stripe and OpenAI for founders and operators across consumer AI, vertical AI, frontier models, data and chips, in a relaxed setting. Collaborative Fund invests from seed to growth across the AI stack, so it is a direct way to meet investors and fellow founders. Few seats; apply to join. End time not announced."}, {"link": "https://www.tech-week.com/calendar/sf/events/growth-engineering-perplexity-d49bb010-b202-4264-81e8-6e0bab63530b", "why_en": "An open evening with Perplexity's Growth team. Co-founder Johnny Ho, VP of Product Raman Malik, Head of Growth Engineering Sophia Feng and others start with a fireside on how they run experiments, grow an AI product and what they are shipping, followed by time to mingle with the whole Growth team. Good for people who want to learn growth, and for engineers considering a role at Perplexity."}, {"link": "https://partiful.com/e/ljNVe4NFK28RZbWMcLbP", "why_en": "A dinner by a16z and Stripe for venture-backed B2B AI founders, about pricing: when agents use your product too, do you charge per seat, by usage, or both? Welcome drinks, a panel with Q&A, dinner and networking. Invitation only, very limited seats."}, {"link": "https://www.tech-week.com/calendar/sf/events/benchmark-ai-dinner-ba499313-e472-48c8-96ea-20a9b6e95704", "why_en": "A dinner co-hosted by Vercel and Benchmark for founders and researchers in AI evals and benchmarking. Vercel CEO Guillermo Rauch and Jack Altman talk over the meal. Small and by application; good for people building evaluation tools or working on model evaluation. Official Tech Week pick. End time not announced."}, {"link": "https://www.tech-week.com/calendar/sf/events/cxo-roundtable-how-enterprise-really-buys-ai-8b52cd7a-ec16-4488-aa5a-a8c0707e6ffd", "why_en": "A panel hosted by a16z speedrun where senior technical executives from large companies explain how enterprises really buy AI, how AI transformation gets done, and how technical leaders work with startups. Speakers include Nivi Baral, CTO of 2K (publisher of NBA 2K and Civilization). Aimed at early-stage technical founders; worth it if you sell B2B into large enterprises. Official Tech Week pick."}, {"link": "https://partiful.com/e/3OvkylJXptvhiEVFZ5wq", "why_en": "Gamma founder Grant Lee on how creator and influencer marketing took the company to 100 million users. First a panel with Wispr Flow, Gamma and Demi.ai on how fast-growing AI companies do influencer marketing, then a fireside with Grant Lee. Good for AI founders and operators who want to learn the growth playbook."}, {"link": "https://partiful.com/e/7gkEjmj2RQD6b0Tx4J0p", "why_en": "A small discussion led by Sarah Fu, Managing Partner at Elsa Capital. With experience as an institutional investor at Fidelity, a banker at Morgan Stanley and an operator at Stripe, she covers how large institutional buyers look at valuation, how banks frame an IPO story, and what to ask beyond the headline numbers. Limited seats, approved one by one."}, {"link": "https://www.tech-week.com/calendar/sf/events/the-founder-reset-zero-to-unicorn-with-bolt-new-ceo-37a3b9c5-f774-4aff-8925-30a1531d715f", "why_en": "A live fireside with Eric Simons, CEO of Bolt.new, on going from an idea and a small early team to a billion-dollar company: the key decisions, turning points and mistakes. In conversation with Gaurav Bhogale, Partner at Mantis Venture Capital; hosted by Unicorner and SimpleClosure, with a coffee bar and wellness station on site. Good for founders who want a first-hand growth story. Official Tech Week pick."}, {"link": "https://www.tech-week.com/calendar/sf/events/fenwick-databricks-a16z-founders-and-investors-happy-hour-eb1357e8-0695-4a80-ad8c-20b80c4f1793", "why_en": "A happy hour co-hosted by Fenwick, Databricks and a16z for founders and investors building or backing data and AI companies. No stage and no pitches, just drinks and honest talk about what is working and what is not. Good for founders who want to meet investors and peers in a relaxed setting. Official Tech Week pick."}, {"link": "https://www.tech-week.com/calendar/sf/events/what-s-next-for-dx-a4f74608-ba44-4a32-a739-080f4f447595", "why_en": "On how developer experience (DX) has to be rebuilt now that agents do much of the coding. On the panel: Tara Hernandez (VP Developer Productivity, MongoDB), Ty Smith (Principal Engineer, Uber), Corey Ching (Member of Technical Staff, OpenAI) and Zander Hill (Architecture Lead, Plaid); DX leaders from Stripe, NVIDIA, LinkedIn, Perplexity and others will be in the room. Hosted by Trunk and EngFlow. Good for engineering leaders and people building developer tools."}, {"link": "https://www.tech-week.com/calendar/sf/events/who-will-own-the-future-7df29c71-1e55-44ef-8828-a9dfc26aa119", "why_en": "Hosted by ARK Invest. Cathie Wood (Founder & CEO, ARK), Andre Iguodala (four-time NBA champion and Co-founder of Mastry), Sarah Pinto (Head of Robinhood Ventures) and others discuss how AI and emerging technologies are reshaping markets and wealth creation, and why scarce assets such as sports may become more valuable. Doors at 18:00 with drinks, food and networking; the program starts at 19:15. One of the best-known speaker lineups of the week. Official Tech Week pick."}, {"link": "https://www.tech-week.com/calendar/sf/events/a16z-speedrun-ai-faire-70750ac4-237e-42a9-9b03-f9589abdae34", "why_en": "A showcase of the AI B2B companies from a16z speedrun cohorts: dozens of founders demo their products live. There is no stage program; walk around and talk to founders directly. Aimed at executives and operators looking to adopt new AI tools, and good for anyone who wants to see a batch of early-stage companies in one go. Entry is staggered; pick a time when you apply. Official Tech Week pick."}, {"link": "https://www.tech-week.com/calendar/sf/events/a16z-x-unicorner-x-notion-the-official-afterparty-44a2ec96-9824-4b06-9fdd-ad01e195887b", "why_en": "The official SF Tech Week afterparty, co-hosted by Unicorner, a16z and Notion: the last big social gathering of the week. You must be approved on Partiful, a government ID is checked at the door, no +1s, and cocktail attire is encouraged. Official Tech Week pick. End time not announced."}, {"link": "https://www.tech-week.com/calendar/sf/events/talk-to-users-hackathon-2ea9ffb9-d4c2-410f-b45c-94eab588be96", "why_en": "A one-day hackathon co-hosted by Stripe, Base44, Cognition, Sense AI, MongoDB, Clerk and others. 20 teams, all technical builders, 12 hours to build a feature that matters. The twist: Sense AI matches each team with real target users, so you test while you build, hear feedback and iterate. $10K+ in prizes, plus lots of credits and 1:1 office hours. Good for engineers who want to build and get real user feedback. Official Tech Week pick."}, {"link": "https://www.tech-week.com/calendar/sf/events/speedhacks-the-official-speedrun-hackathon-30c239a4-638a-4bd6-8d51-e15259668f51", "why_en": "The official closing hackathon of SF Hack Week, hosted by a16z speedrun. One day, 12 hours, starting from zero. The challenge is to give people their time back: build something that removes a real bottleneck in how people work, learn or access services. You can build with tools from speedrun companies, each of which awards a “Best Use” prize. Come with a team or find one on site. Official Tech Week pick."}]$tw$::jsonb) as x(link text, why_en text)
where e.link = x.link and e.source = 'community';

select count(*) filter (where why_en is not null) as with_english, count(*) filter (where source = 'community') as picks from public.techweek_events;
